  ),
  seeded_questions AS (
    INSERT INTO public.questions(subject_id, type, text, answer, options, is_published, source, source_key)
    SELECT v_subject_id, q.type, q.prompt, q.answer, q.options, true, 'import', q.source_key
    FROM question_seed q
    ON CONFLICT (subject_id, source_key) WHERE source_key IS NOT NULL
    DO UPDATE SET type = EXCLUDED.type,
                  text = EXCLUDED.text,
                  answer = EXCLUDED.answer,
                  options = EXCLUDED.options,
                  is_published = true,
                  archived_at = NULL,
                  source = 'import'
    RETURNING id, source_key
  )
  INSERT INTO public.test_questions(test_id, question_id, order_index)
  SELECT v_test_id, q.id, s.question_no
  FROM question_seed s
  JOIN seeded_questions q ON q.source_key = s.source_key
  ON CONFLICT (test_id, question_id)
  DO UPDATE SET order_index = EXCLUDED.order_index;
END $$;

COMMIT;
